import 'package:flutter/material.dart';
import 'package:provider/provider.dart';
import '../models/models.dart';
import '../providers/app_state.dart';
import '../services/backend.dart';

class OrdersScreen extends StatelessWidget { const OrdersScreen({super.key}); @override Widget build(BuildContext context) { final uid = context.read<AppState>().user!.uid; return Scaffold(appBar: AppBar(title: const Text('My orders')), body: StreamBuilder<List<Order>>(stream: FarmRepository().buyerOrders(uid), builder: (context, snap) { if (snap.hasError) return const Center(child: Padding(padding: EdgeInsets.all(28), child: Text('Orders could not be loaded. Check your connection and Firestore rules.', textAlign: TextAlign.center))); if (!snap.hasData) return const Center(child: CircularProgressIndicator()); if (snap.data!.isEmpty) return const Center(child: Padding(padding: EdgeInsets.all(28), child: Text('No orders yet. Browse available produce to get started.', textAlign: TextAlign.center))); return ListView(padding: const EdgeInsets.symmetric(vertical: 10), children: snap.data!.map((o) => OrderCard(order: o)).toList()); })); } }
class OrderCard extends StatelessWidget { const OrderCard({super.key, required this.order}); final Order order; @override Widget build(BuildContext context) { final repo = FarmRepository(); String? next; String? label; if (order.status == 'pending_payment') { next = 'paid_escrow'; label = 'Mock payment'; } else if (order.status == 'paid_escrow') { next = 'delivered'; label = 'Mark delivered'; } else if (order.status == 'delivered') { next = 'released'; label = 'Release payment'; } return Card(margin: const EdgeInsets.all(12), child: Padding(padding: const EdgeInsets.all(16), child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [Text('Order ${order.id.substring(0, 8)}', style: Theme.of(context).textTheme.titleMedium), Text('Amount: ₹${order.amount.toStringAsFixed(2)}'), Text('Status: ${order.status}'), if (next != null) Align(alignment: Alignment.centerRight, child: FilledButton(onPressed: () async { try { await repo.updateOrder(order.id, next!, order.listingId); } catch (e) { if (context.mounted) ScaffoldMessenger.of(context).showSnackBar(SnackBar(content: Text(e.toString()))); } }, child: Text(label!)))]))); } }
